return [{
  json: {
    testOnly: true,
    now: '2026-08-14T12:00:00.000Z',
    child: {
      birthDate: '2025-12-01'
    },
    telegram: {
      interactionId: 'manual-test-context',
      chatId: 'test-chat',
      userId: 'test-user',
      username: 'test-parent',
      type: 'command',
      command: 'status',
      messageText: '/status',
      callbackData: null,
      authorized: true
    },
    recentMeetings: [],
    recentCategories: ['sante', 'culture'],
    topicBacklog: [],
    preferences: {
      sourceLanguages: ['fr', 'en']
    }
  }
}];

const envelope = $json;
const update = envelope.body || envelope;
const message = update.message || update.edited_message || null;
const callbackQuery = update.callback_query || null;
const callbackMessage = callbackQuery?.message || null;
const sourceMessage = message || callbackMessage || {};
const from = callbackQuery?.from || message?.from || {};
const chat = sourceMessage.chat || {};
const text = message?.text || null;
const callbackData = callbackQuery?.data || null;
const command = text && text.startsWith('/') ? text.split(/\s+/)[0].slice(1).split('@')[0] : null;
const type = callbackData ? 'callback' : command ? 'command' : 'message';
const birthDate = ($env.FAMILYHUBOS_CHILD_BIRTH_DATE || '').trim();

return [{
  json: {
    testOnly: false,
    child: birthDate ? { birthDate } : undefined,
    telegram: {
      rawUpdateId: update.update_id?.toString() || null,
      interactionId: callbackQuery?.id || update.update_id?.toString() || `${Date.now()}`,
      chatId: chat.id?.toString() || '',
      userId: from.id?.toString() || '',
      username: from.username || null,
      receivedAt: new Date().toISOString(),
      type,
      command,
      callbackData,
      messageText: text,
      authorized: false,
      payload: {
        updateId: update.update_id || null,
        messageId: sourceMessage.message_id || null,
        callbackQueryId: callbackQuery?.id || null,
        firstName: from.first_name || null,
        lastName: from.last_name || null
      }
    }
  }
}];

const item = $json;
if (item.testOnly) {
  return [{ json: item }];
}

const allowedUsers = ($env.TELEGRAM_ALLOWED_USER_IDS || '').split(',').map(x => x.trim()).filter(Boolean);
const allowedChats = ($env.TELEGRAM_ALLOWED_CHAT_IDS || '').split(',').map(x => x.trim()).filter(Boolean);
const userAllowed = allowedUsers.includes(item.telegram.userId);
const chatAllowed = allowedChats.includes(item.telegram.chatId);

item.telegram.authorized = userAllowed && chatAllowed;
item.telegram.authorization = { userAllowed, chatAllowed };
return [{ json: item }];

const input = $json;
const config = input.config || {};
const family = config.family || {};
const childConfig = family.child || {};
const preferences = {
  ...(family.preferences || {}),
  ...(input.preferences || {})
};

const birthDate = input.child?.birthDate || childConfig.birthDate;
if (!birthDate) {
  if (input.testOnly) {
    return [{ json: { ...input, testResult: { status: 'TEST_FAILED', message: 'Missing child birthDate.' } } }];
  }
  throw new Error('Missing child birthDate. Provide config.family.child.birthDate or input.child.birthDate.');
}

function parseDateOnly(value) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (!match) {
    throw new Error('child birthDate must use YYYY-MM-DD format.');
  }
  return new Date(Date.UTC(Number(match[1]), Number(match[2]) - 1, Number(match[3])));
}

function calculateAgeMonths(startDate, nowDate) {
  let months = (nowDate.getUTCFullYear() - startDate.getUTCFullYear()) * 12;
  months += nowDate.getUTCMonth() - startDate.getUTCMonth();
  if (nowDate.getUTCDate() < startDate.getUTCDate()) {
    months -= 1;
  }
  return Math.max(0, months);
}

function ageLabelFromMonths(months) {
  if (months < 12) return `${months} mois`;
  const years = Math.floor(months / 12);
  const remainingMonths = months % 12;
  if (remainingMonths === 0) return years === 1 ? '1 an' : `${years} ans`;
  return `${years} an${years > 1 ? 's' : ''} et ${remainingMonths} mois`;
}

const now = input.now ? new Date(input.now) : new Date();
const birth = parseDateOnly(birthDate);
const ageMonths = calculateAgeMonths(birth, now);
const child = {
  birthDate,
  ageMonths,
  ageYears: Math.floor(ageMonths / 12),
  ageLabel: ageLabelFromMonths(ageMonths)
};

return [{
  json: {
    ...input,
    familyContext: {
      child,
      recentMeetings: input.recentMeetings || [],
      recentCategories: input.recentCategories || [],
      existingTopics: input.existingTopics || [],
      openDecisions: input.openDecisions || [],
      topicBacklog: input.topicBacklog || [],
      preferences
    }
  }
}];

const input = $json;
const command = input.telegram?.command || null;
const text = input.telegram?.messageText || '';
const categories = input.config?.categories?.allowed || ['developpement','nutrition','sante','culture','musique','sciences','loisirs','parentalite','nature','lecture','autre'];
const route = input.telegram?.type === 'callback' ? 'callback' : command || 'unknown';

let responseText = 'FamilyHubOS est prêt.';
let selectedTopic = input.selectedTopic || null;
let selectedCategory = input.selectedCategory || null;

if (route === 'start') responseText = 'Bienvenue dans FamilyHubOS. Utilise /choose pour préparer le prochain meeting familial.';
if (route === 'help') responseText = 'Commandes disponibles: /start, /help, /status, /choose, /idea.';
if (route === 'status') responseText = `FamilyHubOS fonctionne. Âge calculé: ${input.familyContext.child.ageLabel}.`;
if (route === 'choose') responseText = `Choisis une catégorie: ${categories.join(', ')}`;
if (route === 'idea') {
  selectedTopic = text.replace(/^\/idea(@\w+)?\s*/i, '').trim();
  responseText = selectedTopic ? `Idée reçue: ${selectedTopic}` : 'Ajoute ton idée après /idea.';
}

return [{
  json: {
    ...input,
    route,
    selectedCategory,
    selectedTopic,
    planning: {
      categories,
      responseText
    }
  }
}];

const input = $json;
const topic = input.selectedTopic || 'Sujet de test FamilyHubOS';
const category = input.selectedCategory || 'sciences';

return [{
  json: {
    ...input,
    research: {
      topic,
      category,
      whyNow: `Sujet adapté au contexte actuel de l'enfant (${input.familyContext.child.ageLabel}).`,
      executiveSummary: 'Résumé placeholder: la recherche fiable sera branchée après validation du flux complet.',
      keyPoints: [],
      sources: [],
      discussionQuestions: [
        'Qu voulons-nous comprendre sur ce sujet ?',
        'Qu pouvons-nous tester cette semaine ?'
      ],
      practicalIdeas: [],
      warnings: ['Recherche réelle non branchée: ne pas utiliser ce contenu comme information validée.']
    }
  }
}];

const input = $json;
const acceptedSources = (input.research.sources || []).filter(source => source.accepted || source.score >= 5);
return [{
  json: {
    ...input,
    sourceValidation: {
      total: input.research.sources.length,
      accepted: acceptedSources.length,
      rejected: input.research.sources.length - acceptedSources.length,
      status: acceptedSources.length > 0 ? 'HAS_ACCEPTED_SOURCES' : 'NO_ACCEPTED_SOURCES_YET'
    }
  }
}];

const input = $json;
const meetingNumber = input.meetingNumber || 1;
const date = input.meetingDate || new Date().toISOString();
const title = `Family Meeting #${meetingNumber} - ${input.research.topic}`;

return [{
  json: {
    ...input,
    meeting: {
      id: `familyhubos-meeting-${meetingNumber}`,
      number: meetingNumber,
      title,
      topic: input.research.topic,
      category: input.research.category,
      date,
      childAgeLabel: input.familyContext.child.ageLabel,
      status: 'Ready',
      preparationStatus: 'Ready',
      readingTimeMinutes: 0,
      sourceCount: input.sourceValidation.accepted
    },
    notionPayload: {
      status: 'PLACEHOLDER_NOT_CREATED',
      title
    },
    calendarPayload: {
      status: 'PLACEHOLDER_NOT_CREATED',
      summary: title
    }
  }
}];

const input = $json;
const success = input.testOnly
  ? input.familyContext.child.ageMonths === 8 && input.familyContext.child.ageLabel === '8 mois'
  : true;

return [{
  json: {
    testOnly: Boolean(input.testOnly),
    status: success ? 'TEST_SUCCESS' : 'TEST_FAILED',
    message: success
      ? `FamilyHubOS workflow OK. Child age: ${input.familyContext.child.ageLabel}. Route: ${input.route}.`
      : 'FamilyHubOS workflow test failed.',
    route: input.route,
    responseText: input.planning.responseText,
    telegram: input.telegram,
    familyContext: input.familyContext,
    meeting: input.meeting,
    researchStatus: input.sourceValidation.status,
    nextRealIntegrations: ['Notion create page', 'Google Calendar create event', 'Web search provider']
  }
}];
